<?php
require_role(['admin','officer']);$system=geo_system();$officer=user()['role']==='officer';$tab=(string)($_GET['tab']??($officer?'towns':'overview'));$allowed=$system?['overview','accounts','towns','legacy']:($officer?['towns']:['overview','accounts','towns']);if(!in_array($tab,$allowed,true))$tab=$allowed[0];
layout_start('Province routing','Citizen → Province Admin → District Officer → Town Maintenance Team');
$provinces=geo_raw('SELECT p.*,u.name admin_name,u.active admin_active FROM geo_provinces p LEFT JOIN users u ON u.id=p.admin_id'.($system?'':' WHERE p.id IN ('.implode(',',geo_province_ids()?:[0]).')').' ORDER BY p.name')->fetchAll();
$district_ids=$system?array_column(geo_raw('SELECT id FROM geo_districts')->fetchAll(),'id'):($officer?geo_district_ids():array_column(geo_raw('SELECT id FROM geo_districts WHERE province_id IN ('.implode(',',geo_province_ids()?:[0]).')')->fetchAll(),'id'));$district_ids=array_map('intval',$district_ids);
$districts=geo_raw('SELECT d.*,p.name province,o.name officer_name,o.active officer_active FROM geo_districts d JOIN geo_provinces p ON p.id=d.province_id LEFT JOIN users o ON o.id=d.officer_id WHERE d.id IN ('.implode(',',$district_ids?:[0]).') ORDER BY p.name,d.name')->fetchAll();
?><div class="admin-workspace"><p><a class="text-link" href="index.php?page=flow&amp;tab=teams">Configure team service categories →</a> · <a class="text-link" href="index.php?page=flow&amp;tab=handover">Absence / handover guidance →</a></p><nav class="admin-tabs" aria-label="Routing management"><?php foreach(['overview'=>'Province / district responsibility','accounts'=>'Scoped accounts','towns'=>'Towns / maintenance teams','legacy'=>'Legacy reports to classify'] as $key=>$label):if(!in_array($key,$allowed,true))continue;?><a class="<?=$tab===$key?'selected':''?>" href="index.php?page=routing&amp;tab=<?=$key?>"><?=$label?></a><?php endforeach;?></nav>
<?php if($tab==='overview'):?><section class="panel"><h2>Province Admin coverage</h2><p class="small muted">One Province Admin login per province. District Officers and maintenance teams are configured below. Missing or disabled accounts leave reports in the relevant province queue until configured.</p><div class="table-wrap"><table><thead><tr><th>Province</th><th>Province Admin</th><th>Readiness</th><th>Open reports</th></tr></thead><tbody><?php foreach($provinces as $p):?><tr><td><?=e($p['name'])?></td><td><?=e($p['admin_name']?:'Not configured')?></td><td><?=badge($p['admin_id']&&$p['admin_active']?'Active':'Action needed')?></td><td><?=(int)q("SELECT COUNT(*) FROM issues WHERE province_id=? AND status NOT IN ('Resolved','Rejected','Duplicate')",[$p['id']])->fetchColumn()?></td></tr><?php endforeach;?></tbody></table></div></section><section class="panel section-space"><h2>District Officer responsibility</h2><div class="table-wrap"><table><thead><tr><th>District</th><th>Province</th><th>District Officer</th><th>Readiness</th></tr></thead><tbody><?php foreach($districts as $d):?><tr><td><?=e($d['name'])?></td><td><?=e($d['province'])?></td><td><?=e($d['officer_name']?:'Not configured')?></td><td><?=badge($d['officer_id']&&$d['officer_active']?'Active':'Action needed')?></td></tr><?php endforeach;?></tbody></table></div><p class="small muted">Province Admin assigns each verified report to the configured officer for its district. The District Officer chooses a team registered for that report’s town.</p></section>
<?php elseif($tab==='accounts'):?><section class="panel"><h2>Create a scoped account</h2><p class="small muted">Use real email addresses and a temporary password. No default accounts or passwords are created by the database update. Account holders change their password under My profile.</p><form method="post"><?php csrf();?><input type="hidden" name="action" value="geo_create_account"><div class="admin-filter-grid"><label>Name / team name<input name="name" minlength="2" maxlength="100" required></label><label>Email<input type="email" name="email" maxlength="190" required></label><label>Temporary password<input type="password" name="password" minlength="10" maxlength="72" autocomplete="new-password" required></label><label>Account type<select name="account_kind" data-geo-account-kind><?php if($system):?><option value="province">Province Admin</option><?php endif;?><option value="district">District Officer</option><option value="town">Town Maintenance Team</option></select></label></div><?php geo_location_selector([],false,true);?><p class="small muted">Province Admin: province only. District Officer: province + district. Maintenance team: all three. An account cannot manage two provinces or two districts.</p><button class="button">Create scoped account</button></form></section>
<?php if($system):?><section class="panel section-space"><h2>Configure an existing account</h2><p class="small muted">Old Officer and Maintenance accounts remain available. Configure their district/town before dispatching new work. Your current System Admin login stays central. Another existing admin can be converted into a Province Admin here; its global access is removed and its sessions are invalidated.</p><?php foreach(['province'=>['Province Admin','admin','geo_provinces'],'district'=>['District Officer','officer','geo_districts'],'town'=>['Town Maintenance Team','maintenance','geo_towns']] as $kind=>$info):$people=geo_raw('SELECT id,name,email,is_system_admin FROM users WHERE role=? AND active=1'.($kind==='province'?' AND id<>'.(int)user()['id']:'').' ORDER BY name',[$info[1]])->fetchAll();$targets=$kind==='province'?geo_raw('SELECT id,name FROM geo_provinces ORDER BY name')->fetchAll():($kind==='district'?geo_raw('SELECT d.id,CONCAT(p.name,\' / \',d.name) name FROM geo_districts d JOIN geo_provinces p ON p.id=d.province_id ORDER BY p.name,d.name')->fetchAll():geo_raw('SELECT t.id,CONCAT(d.name,\' / \',t.name) name FROM geo_towns t JOIN geo_districts d ON d.id=t.district_id WHERE t.active=1 ORDER BY d.name,t.name')->fetchAll());?><details class="section-space" <?=($_GET['mapping']??'')===$kind?'open':''?>><summary><?=e($info[0])?> mapping</summary><form method="post" data-confirm="Save this account scope? The selected account must sign in again. Existing responsibility may change."><?php csrf();?><input type="hidden" name="action" value="geo_map_account"><input type="hidden" name="mapping_kind" value="<?=$kind?>"><div class="two-col"><label>Active account<select name="user_id" required><option value="">Choose account</option><?php foreach($people as $person):?><option value="<?=$person['id']?>" <?=((int)($_GET['user_id']??0)===(int)$person['id'])?'selected':''?>><?=e($person['name'].' · '.$person['email'].($kind==='province'&&$person['is_system_admin']?' · converts global admin to province scope':''))?></option><?php endforeach;?></select></label><label>Assigned <?=$kind?><select name="target_id" required><option value="">Choose <?=$kind?></option><?php foreach($targets as $target):?><option value="<?=$target['id']?>"><?=e($target['name'])?></option><?php endforeach;?></select></label></div><?php if($kind==='district'):?><label class="check-label"><input type="checkbox" name="transfer_open" value="1"> Transfer this district’s current open work to the selected officer (if any).</label><label>Handover reason (required when transferring open work)<textarea name="handover_note" minlength="5" maxlength="2000"></textarea></label><p class="small muted">Current status, town team and evidence stay with each report. Previous form versions become stale.</p><?php endif;if($kind==='province'):?><label>Your System Admin password<input type="password" name="admin_password" autocomplete="current-password" required></label><p class="small muted">Converting an existing global administrator removes its global permissions. Your current System Admin login is kept.</p><?php endif;?><label>Reason for responsibility change<textarea name="change_reason" minlength="5" maxlength="2000" required></textarea></label><button class="button secondary">Save <?=$kind?> mapping</button></form></details><?php endforeach;?></section><?php endif;?>
<?php elseif($tab==='towns'):$towns=geo_raw('SELECT t.*,d.name district,p.name province FROM geo_towns t JOIN geo_districts d ON d.id=t.district_id JOIN geo_provinces p ON p.id=d.province_id WHERE d.id IN ('.implode(',',$district_ids?:[0]).') ORDER BY p.name,d.name,t.name')->fetchAll();?>
<section class="panel"><h2>Add a town / maintenance area</h2><p class="small muted">A starter set of towns is included. Add the actual major towns your maintenance operation covers. Town names belong to a district; the map pin does not determine this automatically.</p><form method="post"><?php csrf();?><input type="hidden" name="action" value="geo_create_town"><?php geo_location_selector([],false,true);?><label>New town name<input name="name" minlength="2" maxlength="100" required></label><button class="button secondary">Add town</button></form></section>
<section class="panel section-space"><h2>Towns and active maintenance teams</h2><div class="table-wrap"><table><thead><tr><th>Town</th><th>District</th><th>Province</th><th>Active maintenance teams</th></tr></thead><tbody><?php foreach($towns as $t):$teams=geo_raw("SELECT name FROM users WHERE role='maintenance' AND active=1 AND town_id=? ORDER BY name",[$t['id']])->fetchAll();?><tr><td><?=e($t['name'])?></td><td><?=e($t['district'])?></td><td><?=e($t['province'])?></td><td><?=e($teams?implode(', ',array_column($teams,'name')):'No team configured')?></td></tr><?php endforeach;?></tbody></table></div></section>
<?php else:geo_system_required();$total=(int)geo_raw('SELECT COUNT(*) FROM issues WHERE province_id IS NULL OR district_id IS NULL OR town_id IS NULL')->fetchColumn();$pages=max(1,(int)ceil($total/20));$pn=min($pages,max(1,(int)($_GET['p']??1)));$rows=geo_raw('SELECT * FROM issues WHERE province_id IS NULL OR district_id IS NULL OR town_id IS NULL ORDER BY id LIMIT 20 OFFSET '.(($pn-1)*20))->fetchAll();?>
<section class="panel"><h2><?=$total?> legacy reports need a location classification</h2><p class="small muted">No location is guessed from an old address or map pin. Classifying active work returns it to Submitted and clears its previous assignment; all existing evidence and history stay available. Closed reports remain closed.</p><?php foreach($rows as $r):?><details class="section-space"><summary>#<?=$r['id']?> · <?=e($r['title'])?> · <?=e($r['status'])?></summary><p><?=e($r['address'])?></p><a class="text-link" href="index.php?page=issue&amp;id=<?=$r['id']?>">View report and evidence →</a><form method="post" data-confirm="Route this legacy report? Active work returns to review and previous assignments are cleared; evidence and history remain."><?php csrf();?><input type="hidden" name="action" value="geo_classify"><input type="hidden" name="issue_id" value="<?=$r['id']?>"><input type="hidden" name="previous_updated" value="<?=e($r['updated_at'])?>"><?php geo_location_selector();?><label>Classification reason<textarea name="note" minlength="5" maxlength="2000" required></textarea></label><button class="button secondary">Route to province</button></form></details><?php endforeach;admin_pager($pn,$pages,$total);?></section>
<?php endif;?></div><?php layout_end();
